function renderHome(){const q=Q.quote({price,sourceTime:lastSourceTime}),fresh=live&&q.usable,f=currentForecast||{},usable=fresh&&f.ready&&Date.now()-Date.parse(f.generatedAt)>=0&&Date.now()-Date.parse(f.generatedAt)<30*60000;$('homePrice').textContent=price>0?money(price):'—';$('homeGram21').textContent=fresh?money(price/P.TROY_OUNCE*21/24):'—';$('homeGram24').textContent=fresh?money(price/P.TROY_OUNCE):'—';$('homeFeed').textContent=fresh?'سعر حديث':price>0?'سعر يحتاج تحديثاً':'بانتظار السعر';$('homeSource').textContent=(quoteSource||'المصدر غير متاح')+(lastSourceTime?' • عمر السعر '+Math.max(0,Math.floor((Date.now()-lastSourceTime)/1000))+' ثانية':' • وقت المصدر غير معروف');const b24=usable?f.h24?.bias:null,b48=usable?f.h48?.bias:null,labels={BULLISH:'ميل صاعد',BEARISH:'ميل هابط',NEUTRAL:'متذبذب'};$('home24').textContent=labels[b24]||'غير جاهز';$('home48').textContent=labels[b48]||'غير جاهز';let title='البيانات لا تكفي لقرار واضح',reason='بيانات حركة السعر غير مكتملة أو غير موثوقة بعد. تفاصيل المصدر موجودة في التحليل.',step='انتظر تحديث البيانات؛ راجع عرض الصائغ قبل أي قرار.';if(usable){title=b24==='BULLISH'&&b48==='BULLISH'?'ميل صاعد خلال يومين':b24==='BEARISH'&&b48==='BEARISH'?'ميل هابط خلال يومين':'الاتجاه غير محسوم';reason=(f.reasonsAr||[]).slice(0,2).join(' • ')||'الإشارات لا تعطي اتجاهاً واضحاً.';step=b24==='BULLISH'&&b48==='BULLISH'?'إذا كنت تفكر بالشراء، قارن كلفة الصائغ أولاً؛ الصعود المحتمل قد لا يغطي فرق البيع.':b24==='BEARISH'&&b48==='BEARISH'?'إذا كنت تفكر بالبيع، راجع صافي عرض الصائغ مقابل كلفتك؛ الميل الهابط لا يضمن استمرار الهبوط.':'لا يوجد اتجاه متفق عليه بين 24 و48 ساعة؛ التريث خيار متاح.';if(f.eventRisk24h)step='حدث عالي التأثير قريب؛ الاتجاه قد يتبدل بسرعة. راجع التفاصيل قبل القرار.';}else if(!fresh)reason=!live?'تعذر الاتصال بمصدر السعر؛ التحليل معلّق.':Q.reasons[q.status]||'وقت السعر غير موثوق.';$('homeModelContext').textContent=usable?((Number(macro.quality)||0)<30?'تحليل فني قصير؛ بيانات الاقتصاد غير كافية. ':'تحليل فني وعوامل اقتصادية متاحة. ')+'دقة التوقعات غير مثبتة؛ راجع سجل النتائج في التحليل.':'لا نعرض اتجاهاً عند غياب بيانات موثوقة.';$('homeOutlook').textContent=title;$('homeExplanation').textContent=reason;$('homeNextStep').textContent=step;const count=physicalPieces.reduce((n,x)=>n+x.quantity,0);$('homeHoldings').textContent=count?count+' قطعة في محفظتك':'أضف قطعك وكلفتها';}
function currentLocalForecast(){if(!live||!Q.quote({price,sourceTime:lastSourceTime}).usable)return {ready:false,action:'WAIT',messageAr:'السعر غير موثق أو متأخر؛ التوقع معلّق'};return Forecast.analyze(candleSets.M15,{...macro,calendar,eventRisk24h:calendar.risk24h,eventRisk48h:calendar.risk48h},C)}
function evaluateJournal(){let changed=false;forecastJournal=forecastJournal.map(x=>{const before=JSON.stringify(x.evaluations||{}),n=J.evaluate(x,candleSets.M1?.bars||[]);if(JSON.stringify(n.evaluations)!==before)changed=true;return n});if(changed)saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal)}
function recordForecast(f){if(!f?.ready||!f.referenceTime||f.modelVersion!==J.MODEL)return;const id=J.MODEL+'-'+f.referenceTime;if(forecastJournal.some(x=>x.id===id))return;forecastJournal=J.merge(forecastJournal,[{id,modelVersion:J.MODEL,referenceTime:f.referenceTime,createdAt:f.generatedAt,price:f.currentPrice,h24:f.h24,h48:f.h48,action:f.action,evaluations:{}}]);saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal)}
function journalStats(){const calc=key=>{const r=J.stats(archiveJournal??forecastJournal,key);return {n:r.n,dir:r.accuracy==null?null:Math.round(r.accuracy),interval:r.interval}};return {h24:calc('h24'),h48:calc('h48')}}
function renderAccuracy(){evaluateJournal();const visible=archiveJournal??forecastJournal,s=journalStats();$('acc24').textContent=s.h24.dir==null?'—':s.h24.dir+'%';$('acc24n').textContent=`${s.h24.n} نتائج`+(s.h24.interval?` • نطاق عدم اليقين ${s.h24.interval.map(Math.round).join('–')}%`:'');$('acc48').textContent=s.h48.dir==null?'—':s.h48.dir+'%';$('acc48n').textContent=`${s.h48.n} نتائج`+(s.h48.interval?` • نطاق عدم اليقين ${s.h48.interval.map(Math.round).join('–')}%`:'');const allN=s.h24.n+s.h48.n,rangeHits=visible.filter(x=>x.modelVersion===J.MODEL&&!x.importedUnverified).flatMap(x=>[x.evaluations?.h24,x.evaluations?.h48]).filter(Boolean);$('rangeAcc').textContent=allN?Math.round(rangeHits.filter(x=>x.rangeHit).length/allN*100)+'%':'—';$('forecastCount').textContent=visible.length;
 $('accuracyRows').innerHTML=visible.slice(-12).reverse().map(x=>{const a=x.evaluations?.h24,b=x.evaluations?.h48,result=[a?`${a.directionHit?'✓':'✕'}24h`:null,b?`${b.directionHit?'✓':'✕'}48h`:null].filter(Boolean).join(' / ')||'بانتظار';return `<tr><td>${new Date(x.createdAt).toLocaleString('ar')}</td><td>${money(x.price)}</td><td>${escapeHtml(x.h24?.biasAr||'—')} ${x.h24?.modelScore??'—'}/100</td><td>${escapeHtml(x.h48?.biasAr||'—')} ${x.h48?.modelScore??'—'}/100</td><td>${result}</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد توقعات بعد.</td></tr>';
}
function renderForecast(){const fresh=live&&Q.quote({price,sourceTime:lastSourceTime}).usable;currentForecast=fresh&&remoteForecast?.ready&&remoteForecast.modelVersion===J.MODEL&&candleSets.M15?.ready&&remoteForecast.referenceTime===candleSets.M15.bars.at(-1)?.end&&Date.now()-Date.parse(remoteForecast.generatedAt)>=0&&Date.now()-Date.parse(remoteForecast.generatedAt)<30*60000?remoteForecast:currentLocalForecast();const f=currentForecast||{};if(f.ready)recordForecast(f);const cls=f.action==='WATCH_BUY'?'buy':f.action==='WATCH_SELL'?'sell':'wait';$('forecastStatus').className='forecast-status '+cls;$('forecastStatus').textContent=f.ready?`${f.actionAr||'انتظار'} • ${f.sequenceAr||''} • جودة البيانات ${Math.round(f.dataQuality||0)}%`:(f.messageAr||'جاري تجهيز التوقع');
 const set=(p,h)=>{if(!h){$(p+'Bias').textContent='—';$(p+'Probability').textContent='—';$(p+'Range').textContent='—';$(p+'Confidence').textContent='—';$(p+'Invalidation').textContent='—';return}$(p+'Bias').textContent=h.biasAr||h.bias;$(p+'Probability').textContent='أوزان نموذج تجريبية؛ ليست احتمالات نجاح';$(p+'Range').textContent=`${money(h.low)} — ${money(h.high)}`;$(p+'Confidence').textContent=`درجة النموذج ${h.modelScore??'—'}/100 • المركز ${money(h.center)}`;$(p+'Invalidation').textContent=h.invalidation?`إلغاء السيناريو قرب ${money(h.invalidation)}`:'لا يوجد مستوى إلغاء اتجاهي'};set('f24',f.h24);set('f48',f.h48);
 $('forecastReasons').innerHTML=(f.reasonsAr||[]).slice(0,8).map(x=>`<span>${escapeHtml(x)}</span>`).join('');$('forecastWarning').hidden=!f.warningAr;$('forecastWarning').textContent=f.warningAr||'';$('macroStatus').textContent=`المصادر ${macro.status||'—'} • جودة ${Math.round(macro.quality||0)}% • الأثر العالمي ${macro.compositeScore==null?'غير متاح':Number(macro.compositeScore).toFixed(1)}`;const s=journalStats();$('forecastAccuracy').textContent=(s.h24.n||s.h48.n)?`نتائج هذا الإصدار: 24h ${s.h24.dir??'—'}% (${s.h24.n}) • 48h ${s.h48.dir??'—'}% (${s.h48.n})؛ ليست ضماناً للتوقع التالي`:'لا نتائج موثقة بعد؛ يلزم إغلاق M1 عند موعد 24/48 ساعة. السجل القديم غير محسوب.';renderAccuracy();renderHome()}
function factorDirection(name,v){if(!v||v.latest===null||v.latest===undefined||v.latest===''||!Number.isFinite(Number(v.latest)))return 'غير متاح';if(v.status&&v.status!=='available')return v.status==='stale'?'بيانات قديمة • '+(v.date||''):'بيانات غير كافية';if(v.changePct===null||v.changePct===undefined||!Number.isFinite(Number(v.changePct)))return 'تغير غير متاح';const ch=Number(v.changePct),supportive=['VIX','النفط'].includes(name)?ch>0:ch<0,unit=v.unit==='percentage-points'?' نقطة مئوية':'%';return `${Number(v.latest).toFixed(2)} • ${ch>=0?'+':''}${ch.toFixed(2)}${unit} • ${ch===0?'دون تغير':supportive?'داعم محتمل':'ضاغط محتمل'}${v.date?' • '+v.date:''}`}

function marketRegime(){const news=Math.abs(Number(macro.news?.score)||0),vix=Number(macro.factors?.vix?.changePct)||0;if(calendar.risk24h)return '⚠️ سوق أخبار عالية التأثير';if(news>=20)return '🌍 سوق أخبار/جيوسياسة';if(lastAnalysis?.ready&&Number(lastAnalysis.strength)>=80)return '📈 اتجاه فني قوي';if(vix>5)return '🛡️ سوق توتر/ملاذ آمن';return '↔️ سوق مختلط/متذبذب'}
function renderMacro(){$('marketRegime').textContent=marketRegime();const f=macro.factors||{},items=[['الدولار',f.usd],['عائد 10 سنوات',f.yield10],['عائد سنتين',f.yield2],['الفائدة الفعلية',f.fedFunds],['VIX',f.vix],['S&P 500',f.sp500],['Nasdaq',f.nasdaq],['النفط',f.oil]];$('macroFactors').innerHTML=items.filter(([,v])=>v).map(([n,v])=>`<div><span>${n}</span><b class="${factorDirection(n,v).includes('داعم محتمل')?'up':factorDirection(n,v).includes('ضاغط محتمل')?'down':'muted'}">${escapeHtml(factorDirection(n,v))}</b></div>`).join('')||'<div><span>العوامل</span><b>بانتظار الاتصال</b></div>';
 const news=macro.news?.headlines||[];$('newsRadar').innerHTML=news.slice(0,8).map(x=>`<li>${escapeHtml(x.title||'')} ${x.domain?`<small>— ${escapeHtml(x.domain)}</small>`:''}</li>`).join('')||'<li>لا توجد عناوين متاحة حالياً.</li>'}
function eventCountdown(ts){const ms=Number(ts)-Date.now();if(ms<=0)return 'الآن/صدر';const m=Math.round(ms/60000),d=Math.floor(m/1440),h=Math.floor((m%1440)/60),min=m%60;if(d)return `بعد ${d}ي ${h}س`;if(h)return `بعد ${h}س ${min}د`;return `بعد ${min}د`}
function renderCalendar(){const events=(calendar.events||[]).filter(e=>Number(e.timestamp)>Date.now()-3600000).slice(0,10),n=calendar.nextHigh;$('calendarStatus').textContent=`${calendar.status||'—'} • ${events.length} أحداث قادمة${calendar.errors?.length?' • بعض المصادر متأخرة':''}`;$('nextEvent').innerHTML=n?`<b>⚠️ ${escapeHtml(n.titleAr||n.title)}</b><small>${eventCountdown(n.timestamp)} • ${new Date(n.timestamp).toLocaleString('ar')} • ${escapeHtml(n.source||'')}</small>`:'<b>لا يوجد حدث عالي التأثير قريب ضمن البيانات المتاحة.</b>';$('calendarEvents').innerHTML=events.map(e=>`<div class="event-row"><div class="event-time">${new Date(e.timestamp).toLocaleDateString('ar',{month:'short',day:'numeric'})}<br>${new Date(e.timestamp).toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'})}</div><div><b>${escapeHtml(e.titleAr||e.title)}</b><small>${escapeHtml(e.source||'')} • ${eventCountdown(e.timestamp)}</small></div><span class="impact ${e.impact==='high'?'high':'medium'}">${e.impact==='high'?'عالي':'متوسط'}</span></div>`).join('')||'<div class="muted">لا توجد أحداث في القائمة الآن.</div>'}
function renderPaper(){if(!paper||typeof paper!=='object')paper={startCash:10000,cash:10000,oz:0,avgCost:0,realized:0,trades:[],auto:false,lastAutoSignal:'WAIT'};const equity=Number(paper.cash||0)+Number(paper.oz||0)*Number(price||0),pl=equity-Number(paper.startCash||10000);$('paperCash').textContent=money(paper.cash);$('paperOz').textContent=(Number(paper.oz)||0).toFixed(4)+' oz';$('paperEquity').textContent=money(equity);$('paperPL').textContent=(pl>=0?'+':'')+money(pl);$('paperPL').style.color=pl>0?'var(--buy)':pl<0?'var(--sell)':'';$('paperAuto').checked=!!paper.auto;$('paperRows').innerHTML=(paper.trades||[]).slice(-12).reverse().map(t=>`<tr><td>${new Date(t.time).toLocaleString('ar')}</td><td>${t.side==='BUY'?'شراء':'بيع'}</td><td>${money(t.execPrice)}</td><td>${Number(t.oz).toFixed(4)}</td><td>${money(t.value)}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد صفقات تجريبية.</td></tr>'}
function paperBuy(amount,auto=false){amount=Math.min(Math.max(0,Number(amount)||0),Number(paper.cash||0));if(!live||!Q.quote({price,sourceTime:lastSourceTime}).usable||!(price>0)||amount<10)return false;const exec=price*(1+SPREAD),oz=amount/exec,oldOz=Number(paper.oz||0),oldCost=oldOz*Number(paper.avgCost||0);paper.cash-=amount;paper.oz=oldOz+oz;paper.avgCost=(oldCost+amount)/paper.oz;paper.trades=[...(paper.trades||[]),{time:Date.now(),side:'BUY',marketPrice:price,execPrice:exec,oz,value:amount,auto}].slice(-300);saveJSON(userKey('gold_paper'),paper);renderPaper();return true}
function paperSell(auto=false){const oz=Number(paper.oz||0);if(!live||!Q.quote({price,sourceTime:lastSourceTime}).usable||!(price>0)||oz<=0)return false;const exec=price*(1-SPREAD),value=oz*exec,cost=oz*Number(paper.avgCost||0);paper.cash+=value;paper.realized=Number(paper.realized||0)+(value-cost);paper.trades=[...(paper.trades||[]),{time:Date.now(),side:'SELL',marketPrice:price,execPrice:exec,oz,value,auto}].slice(-300);paper.oz=0;paper.avgCost=0;saveJSON(userKey('gold_paper'),paper);renderPaper();return true}
function maybePaperAuto(a){if(!paper.auto||!a?.ready)return;if(a.side==='WAIT'){paper.lastAutoSignal='WAIT';saveJSON(userKey('gold_paper'),paper);return}const threshold=a.side==='BUY'?Number(C.buyThreshold||75):Number(C.sellThreshold||75);if(a.strength<threshold||paper.lastAutoSignal===a.side)return;if(a.side==='BUY')paperBuy(Math.min(1000,Number(paper.cash||0)*.25),true);if(a.side==='SELL')paperSell(true);paper.lastAutoSignal=a.side;saveJSON(userKey('gold_paper'),paper)}
function render(){if(!(price>0))return;const a=Engine.analyze({connected:live,quote:{price,sourceTime:lastSourceTime},candles:candleSets},C);lastAnalysis=a;$('price').textContent=money(price);renderPhysical();
 const sig=$('signal');sig.textContent=a.side;sig.className='signal '+String(a.side||'WAIT').toLowerCase();$('rsi').textContent=a.rsi==null?'—':Number(a.rsi).toFixed(1);$('ema').textContent=a.ema9&&a.ema21?(a.ema9>a.ema21?'↑ صاعد':'↓ هابط'):'—';$('momentum').textContent=a.momentum==null?'—':`${a.momentum>=0?'+':''}${Number(a.momentum).toFixed(3)}%`;$('strength').textContent=(a.strength||0)+'/100';$('warmup').textContent=a.ready?'':(a.reasonsAr?.[0]||'بانتظار شموع موثقة');$('sampleCount').textContent=`${history.length} قراءة حقيقية`;
 const plan=a.plan||{};$('entry').textContent=a.plan?money(plan.entry):'—';$('sl').textContent=money(plan.stopLoss);$('tp1').textContent=money(plan.takeProfit1);$('tp2').textContent=money(plan.takeProfit2);$('signalReasons').innerHTML=(lang==='ar'?a.reasonsAr:a.reasons).map(x=>`<span>${escapeHtml(x)}</span>`).join('');renderQuality();drawChart();renderForecast();renderMacro();renderCalendar();renderPaper();applyLang();updateTime();maybePaperAuto(a)}
function drawChart(){const samples=R.summary(observedQuotes).samples.slice(-720);$('sampleCount').textContent=samples.length+' قراءة مرصودة • خط متقطع عند الفجوات';if(!samples.length){$('line').setAttribute('d','');$('area').setAttribute('d','');return}const w=600,h=220,pad=14,vals=samples.map(r=>r.price),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,.01),first=samples[0].sourceTime,span=Math.max(30000,samples.at(-1).sourceTime-first);let path='';const pts=samples.map((r,i)=>{const x=pad+(r.sourceTime-first)/span*(w-pad*2),y=pad+(1-(r.price-min)/range)*(h-pad*2);path+=(i===0||r.sourceTime-samples[i-1].sourceTime>R.GAP?'M ':' L ')+x+' '+y;return [x,y]});$('line').setAttribute('d',path);$('area').setAttribute('d','');$('lastPoint').setAttribute('cx',pts.at(-1)[0]);$('lastPoint').setAttribute('cy',pts.at(-1)[1])}
function animatePrice(next){if(previousPrice==null){previousPrice=next;return}const diff=next-previousPrice,p=previousPrice?diff/previousPrice*100:0;$('priceArrow').textContent=diff>0?'▲':diff<0?'▼':'•';$('priceArrow').className='price-arrow '+(diff>0?'up':diff<0?'down':'');$('priceChange').textContent=`${diff>0?'+':''}${diff.toFixed(2)} (${p>0?'+':''}${p.toFixed(3)}%)`;$('priceChange').className='price-change '+(diff>0?'up':diff<0?'down':'');$('price').classList.remove('flash-up','flash-down');void $('price').offsetWidth;if(diff!==0)$('price').classList.add(diff>0?'flash-up':'flash-down');previousPrice=next}
function renderQuality(){renderHome();renderPurchaseTime();renderPhysical();renderRecorder();const q=Q.quote({price,sourceTime:lastSourceTime}),usable=live&&q.usable;quoteState=q;const message=live?(Q.reasons[q.status]||q.status):'الاتصال مقطوع؛ الإشارات معلّقة';$('feedStatus').textContent=usable?'سعر حديث':message;$('liveDot').classList.toggle('on',usable);$('dataQualityStatus').textContent=message+(quoteSource?' • المصدر: '+quoteSource:'');$('candleStatus').textContent=['M1','M5','M15'].map(tf=>{const set=candleSets[tf];const checked=Q.candles({symbol:set?.symbol,source:set?.source,timeframe:tf,candles:set?.bars||[]},tf);return tf+': '+(checked.ready?checked.bars.length+' شمعة مغلقة من '+(set.source||'المصدر'):(set?.reasonAr||checked.reasonAr))}).join(' • ');$('candlePerformance').textContent=(candleRequestMs===null?'لم يُقَس طلب الشموع بعد':'زمن معالجة آخر طلب شموع بالخادم: '+candleRequestMs+' ms')+(candleSets.M1?.latestNativeClosedEnd?' • عمر آخر إغلاق M1 بالمصدر: '+Math.max(0,Math.round((Date.now()-candleSets.M1.latestNativeClosedEnd)/1000))+'ث':'')+' • طلب مجمّع كل '+Math.round(candleRefreshMs/1000)+' ثانية تقريباً • قد يُعلّق M1 بين التحديثات إذا تأخرت الشموع';$('journalStatus').textContent=(journalStatus==='CONNECTED'?'السجل السحابي متصل':journalStatus==='NOT_CONFIGURED'?'الحفظ محلي؛ التخزين السحابي غير مفعّل':'الحفظ محلي؛ المزامنة غير متاحة')+(legacyCount?' • '+legacyCount+' توقع قديم مستبعد من الدقة':'');if(!usable){$('signal').textContent='WAIT';$('signal').className='signal wait';$('strength').textContent='—';for(const id of ['entry','sl','tp1','tp2'])$(id).textContent='—';lastAnalysis=null;}}
async function fetchLive(){try{const r=await fetch((C.marketProxy||'/api/market')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(12000)});if(r.status===401){localStorage.removeItem('gold_token');location.replace('/login');return}const j=await r.json();if(!r.ok)throw Error('Market error');const q=Q.quote(j);quoteRefreshMs=Math.min(60000,Math.max(2000,Number(j.refreshAfterMs)||3000));quoteSource=String(j.source||'').slice(0,120);if(!(q.price>0))throw Error('Invalid price');animatePrice(q.price);price=q.price;lastSourceTime=q.sourceTime;lastFetchAt=Date.now();live=true;if(q.usable){addPoint(price,q.sourceTime);recordQuote({...j,symbol:j.symbol,source:quoteSource})}render()}catch(e){live=false;remoteForecast=null;renderQuality();renderForecast();console.warn('Market feed unavailable')}finally{clearTimeout(pollTimer);pollTimer=setTimeout(fetchLive,Math.max(quoteRefreshMs,Math.max(2,Number(C.pollSeconds)||3)*1000))}}
async function fetchCandles(){try{const r=await fetch('/api/candles?timeframe=ALL',{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(15000)}),j=await r.json();if(!r.ok||!j.timeframes)throw Error();for(const tf of ['M1','M5','M15'])candleSets[tf]=j.timeframes[tf]||{ready:false,bars:[],reasonAr:'إطار غير متاح'};candleRequestMs=Number.isFinite(j.requestMs)?j.requestMs:null;candleRefreshMs=Math.max(60000,Math.min(3600000,Number(j.refreshAfterMs)||60000))}catch{for(const tf of ['M1','M5','M15'])candleSets[tf]={ready:false,reasonAr:'تعذّر تحميل شموع '+tf,bars:[]};candleRequestMs=null}finally{evaluateJournal();if(price>0)render();else renderQuality();clearTimeout(candleTimer);candleTimer=setTimeout(fetchCandles,candleRefreshMs)}}
async function syncJournal(){if(journalBusy)return;journalBusy=true;try{const r=await fetch('/api/journal'+($('journalMonth').value?'?month='+encodeURIComponent($('journalMonth').value):''),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(12000)}),j=await r.json();journalStatus=j.status||'UNAVAILABLE';if(r.ok&&j.status==='CONNECTED'){const selected=$('journalMonth').value;$('journalMonth').innerHTML='<option value="">آخر شهرين</option>'+(j.availableMonths||[]).slice().reverse().map(m=>/^\d{4}-(0[1-9]|1[0-2])$/.test(m)?'<option value="'+m+'">'+m+'</option>':'').join('');$('journalMonth').value=selected;if(selected){archiveJournal=j.entries||[]}else{archiveJournal=null;forecastJournal=J.merge(j.entries||[],forecastJournal);saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal)}renderAccuracy()}}catch{journalStatus='UNAVAILABLE'}finally{journalBusy=false;renderQuality()}}
async function fetchIntelligence(force=false){if(!force&&macroFetchAt&&Date.now()-macroFetchAt<Math.max(5,Number(C.macroRefreshMinutes)||30)*60000)return;try{let r=await fetch((C.forecastProxy||'/api/forecast')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(30000)}),j=await r.json();if(!r.ok)throw Error('Forecast feed error');remoteForecast=j.forecast||null;macro=j.macro||macro;calendar=j.calendar||calendar;macroFetchAt=calendarFetchAt=Date.now();saveJSON('gold_macro_cache',macro);saveJSON('gold_remote_forecast',remoteForecast);saveJSON('gold_calendar_cache',calendar);render()}catch(e){macro={...macro,status:'unavailable',quality:0,compositeScore:null,factors:{},reasonsAr:['تعذر تحديث البيانات الاقتصادية؛ النسخة القديمة مستبعدة من التحليل.'],reasons:[]};remoteForecast=null;calendar=readJSON('gold_calendar_cache',calendar);if(macro)macro={...macro,status:'stale'};console.warn(e);render()}}
async function fetchCalendar(force=false){if(!force&&calendarFetchAt&&Date.now()-calendarFetchAt<15*60000)return;try{const r=await fetch((C.calendarProxy||'/api/calendar')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Calendar feed error');calendar=j;calendarFetchAt=Date.now();saveJSON('gold_calendar_cache',calendar);renderCalendar();renderForecast()}catch(e){console.warn(e);calendar=readJSON('gold_calendar_cache',calendar);renderCalendar()}}
function updateTime(){if(!lastFetchAt){$('lastUpdate').textContent='بانتظار أول قراءة';return}renderQuality();if(!quoteState.usable||!live)renderForecast();const s=Math.max(0,Math.floor((Date.now()-lastFetchAt)/1000)),source=lastSourceTime?new Date(lastSourceTime).toLocaleTimeString(lang==='ar'?'ar':'en',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'';$('lastUpdate').textContent=lang==='ar'?`آخر اتصال منذ ${s}ث • عمر السعر ${lastSourceTime?Math.max(0,Math.floor((Date.now()-lastSourceTime)/1000))+'ث':'غير معروف'} ${source?'• '+source:''}`:`Connected ${s}s ago ${source?'• price '+source:''}`;renderCalendar()}
function applyLang(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i]').forEach(e=>{const k=e.dataset.i;if(!tr[lang]?.[k])return;const b=e.querySelector('b');if(b){const node=b.cloneNode(true);e.textContent=tr[lang][k];e.appendChild(node)}else e.textContent=tr[lang][k]});$('langBtn').textContent=lang==='ar'?'EN':'AR'}

$('langBtn').onclick=()=>{lang=lang==='ar'?'en':'ar';render()};$('shareForecastBtn').onclick=async()=>{const f=currentForecast;if(!f?.h24)return alert('التوقع لم يجهز بعد.');const text=`GOLD AI • ${money(price)}\n24h: ${f.h24.biasAr} • درجة نموذج ${f.h24.modelScore}/100 • ${money(f.h24.low)}–${money(f.h24.high)}\n48h: ${f.h48.biasAr} • درجة نموذج ${f.h48.modelScore}/100\n${f.sequenceAr||''}\nتوقع احتمالي وليس ضماناً.`;try{if(navigator.share)await navigator.share({title:'GOLD AI Forecast',text});else{await navigator.clipboard.writeText(text);alert('تم نسخ بطاقة التوقع.')}}catch{}};$('logoutBtn').onclick=()=>{localStorage.removeItem('gold_token');location.replace('/login')};$('refreshForecastBtn').onclick=()=>fetchIntelligence(true);$('refreshCalendarBtn').onclick=()=>fetchCalendar(true);
$('paperBuyBtn').onclick=()=>{if(!paperBuy(Number($('paperAmount').value)||1000))alert('تأكد من وجود سعر حي ورصيد تجريبي كافٍ.')};$('paperSellBtn').onclick=()=>{if(!paperSell(false))alert('لا يوجد ذهب تجريبي للبيع.')};$('paperResetBtn').onclick=()=>{if(!confirm('إعادة المحفظة التجريبية إلى 10,000$ ومسح الصفقات؟'))return;paper={startCash:10000,cash:10000,oz:0,avgCost:0,realized:0,trades:[],auto:false,lastAutoSignal:'WAIT'};saveJSON(userKey('gold_paper'),paper);renderPaper()};$('paperAuto').onchange=e=>{paper.auto=!!e.target.checked;paper.lastAutoSignal='WAIT';saveJSON(userKey('gold_paper'),paper)};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('installBtn').hidden=false});$('installBtn').onclick=async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('installBtn').hidden=true};
function standalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}
function loadPrefsUi(){$('prefSignals').checked=pushPrefs.signals!==false;$('prefForecasts').checked=pushPrefs.forecasts!==false;$('prefEvents').checked=pushPrefs.events!==false;$('prefNews').checked=!!pushPrefs.news}
async function syncPushTags(OS=oneSignalObj){if(!OS||!username)return;const tags={gold_signals:pushPrefs.signals?'1':'0',gold_forecasts:pushPrefs.forecasts?'1':'0',gold_events:pushPrefs.events?'1':'0',gold_news:pushPrefs.news?'1':'0'};try{await OS.User.addTags(tags)}catch(e){console.warn('OneSignal tags',e)}}
async function savePrefs(){pushPrefs={signals:$('prefSignals').checked,forecasts:$('prefForecasts').checked,events:$('prefEvents').checked,news:$('prefNews').checked};saveJSON(userKey('gold_push_prefs'),pushPrefs);await syncPushTags();alert('تم حفظ تفضيلات الإشعارات لهذا المستخدم.')}
async function initPush(){loadPrefsUi();if(!C.oneSignalAppId){$('notifyStatus').textContent='الإشعارات الخلفية غير مفعّلة بعد من لوحة التحكم.';$('notifyBtn').disabled=$('notifyCardBtn').disabled=true;return}window.OneSignalDeferred=window.OneSignalDeferred||[];window.OneSignalDeferred.push(async OneSignal=>{try{await OneSignal.init({appId:C.oneSignalAppId,serviceWorkerPath:'/push/onesignal/OneSignalSDKWorker.js',serviceWorkerParam:{scope:'/push/onesignal/'},notifyButton:{enable:false},allowLocalhostAsSecureOrigin:true});if(username)await OneSignal.login(username.toLowerCase());oneSignalObj=OneSignal;oneSignalReady=true;await syncPushTags(OneSignal);const enabled=OneSignal.Notifications.permission&&OneSignal.User.PushSubscription.optedIn;updatePushUi(enabled);OneSignal.Notifications.addEventListener('permissionChange',async()=>{const x=OneSignal.Notifications.permission&&OneSignal.User.PushSubscription.optedIn;updatePushUi(x);if(x)await syncPushTags(OneSignal)})}catch(e){$('notifyStatus').textContent='تعذر تهيئة الإشعارات: '+e.message}})}
function updatePushUi(enabled){$('notifyStatus').textContent=enabled?'الإشعارات مفعّلة على هذا الجهاز، والتفضيلات مربوطة بالمستخدم.':'الإشعارات غير مفعّلة على هذا الجهاز.';$('notifyBtn').textContent=$('notifyCardBtn').textContent=enabled?'الإشعارات مفعّلة':'تفعيل الإشعارات';$('notifyBtn').classList.toggle('enabled',enabled)}
async function enablePush(){if(/iPhone|iPad|iPod/.test(navigator.userAgent)&&!standalone()){alert('على iPhone: أضف التطبيق إلى الشاشة الرئيسية، ثم افتحه من الأيقونة وفعّل الإشعارات.');return}if(!oneSignalReady){alert('انتظر لحظة حتى تجهز خدمة الإشعارات.');return}window.OneSignalDeferred.push(async OneSignal=>{try{await OneSignal.Notifications.requestPermission();await OneSignal.User.PushSubscription.optIn();if(username)await OneSignal.login(username.toLowerCase());oneSignalObj=OneSignal;await syncPushTags(OneSignal);updatePushUi(OneSignal.Notifications.permission&&OneSignal.User.PushSubscription.optedIn)}catch(e){alert('تعذر تفعيل الإشعارات: '+e.message)}})}
$('notifyBtn').onclick=enablePush;$('notifyCardBtn').onclick=enablePush;$('savePrefsBtn').onclick=savePrefs;
function assistantReply(q){q=String(q||'').trim().toLowerCase();const f=currentForecast||{},a=lastAnalysis||{},next=calendar.nextHigh,stats=journalStats(),equity=Number(paper.cash||0)+Number(paper.oz||0)*Number(price||0),pl=equity-Number(paper.startCash||10000),news=macro.news||{};if(!q)return 'اكتب سؤالك.';
 if(/سعر|قديش|كم.*ذهب|gold price/.test(q))return `السعر الحي الظاهر عندي الآن ${money(price)} للأونصة. آخر اتصال ${lastFetchAt?new Date(lastFetchAt).toLocaleTimeString('ar'):'غير متاح'}.`;
 if(/بكرا|24|غد|توقع/.test(q)&&!/48|يومين/.test(q)){if(!f.h24)return 'توقع 24 ساعة لم يجهز بعد.';return `توقع 24 ساعة: ${f.h24.biasAr}، درجات النموذج غير معايرة كاحتمالات نجاح. النطاق ${money(f.h24.low)} إلى ${money(f.h24.high)}، ودرجة النموذج ${f.h24.modelScore}/100. ${f.warningAr||''}`}
 if(/48|يومين|بعد يومين/.test(q)){if(!f.h48)return 'توقع 48 ساعة لم يجهز بعد.';return `توقع 48 ساعة: ${f.h48.biasAr}، درجات النموذج غير معايرة كاحتمالات نجاح. النطاق ${money(f.h48.low)} إلى ${money(f.h48.high)}، ودرجة النموذج ${f.h48.modelScore}/100.`}
 if(/ليش|سبب|أسباب|why/.test(q))return `أهم أسباب التحليل الآن:\n• ${(f.reasonsAr||macro.reasonsAr||[]).slice(0,6).join('\n• ')||'لا توجد أسباب كافية بعد.'}\nالإشارة الفنية الحالية ${a.side||'WAIT'} بقوة ${a.strength||0}%.`;
 if(/فدرال|فيدرال|فائدة|خبر|تقويم|متى/.test(q)){if(!next)return 'لا يوجد حدث عالي التأثير قريب ضمن التقويم المتاح حالياً.';return `الحدث العالي القادم: ${next.titleAr||next.title} — ${new Date(next.timestamp).toLocaleString('ar')} (${eventCountdown(next.timestamp)}). قبل الحدث قد تزيد التقلبات، لذلك يخفض المحرك ثقته.`}
 if(/حرب|جيوسي|سياس|أخبار|news/.test(q))return `رادار الأخبار العالمي درجته ${Number(news.score||0).toFixed(1)}. ${Number(news.score)>8?'الميل الإخباري داعم للذهب.':Number(news.score)<-8?'الميل الإخباري ضاغط على الذهب.':'العناوين متوازنة نسبياً.'}\n${(news.headlines||[]).slice(0,3).map(x=>'• '+x.title).join('\n')}`;
 if(/محفظ|تجريب|ربح|خسار|صفقات/.test(q))return `المحفظة التجريبية: القيمة ${money(equity)}، الربح/الخسارة ${(pl>=0?'+':'')+money(pl)}، الذهب ${(Number(paper.oz)||0).toFixed(4)} أونصة، وعدد الصفقات ${(paper.trades||[]).length}.`;
 if(/دقة|نجاح|صح|accuracy/.test(q))return `سجل الحقيقة المحلي: 24 ساعة ${stats.h24.dir==null?'لم تُقَس بعد':stats.h24.dir+'% من '+stats.h24.n+' نتائج'}، و48 ساعة ${stats.h48.dir==null?'لم تُقَس بعد':stats.h48.dir+'% من '+stats.h48.n+' نتائج'}. التوقعات الخاطئة لا تُخفى من السجل.`;
 if(/اشتري|شراء|بيع|ابيع|sell|buy/.test(q)){const sig=a.side||'WAIT',act=f.actionAr||'انتظار';return `الإشارة الفنية الحالية ${sig} بقوة ${a.strength||0}%، والتوقع الأوسع يقول: ${act}. أنا لا أضمن صفقة ولا أرباح؛ إذا كانت المؤشرات أو الأخبار متعارضة فالقرار الأنسب داخل النظام يبقى WAIT، وانتبه لمستوى وقف الخسارة والحدث الاقتصادي القادم.`}
 return `ملخص GOLD AI الآن: السعر ${money(price)}، الإشارة ${a.side||'WAIT'} ${a.strength||0}%، توقع 24h ${f.h24?.biasAr||'غير جاهز'}، توقع 48h ${f.h48?.biasAr||'غير جاهز'}، والأثر العالمي ${macro.compositeScore==null?'غير متاح':Number(macro.compositeScore).toFixed(1)}. اسألني عن السبب، الفيدرالي، الأخبار، الدقة أو المحفظة التجريبية.`}
function addChat(text,type){const d=document.createElement('div');d.className='chat '+type;d.textContent=text;$('assistantChat').appendChild(d);$('assistantChat').scrollTop=$('assistantChat').scrollHeight}
function askAssistant(q){q=String(q||$('assistantInput').value||'').trim();if(!q)return;addChat(q,'user');$('assistantInput').value='';setTimeout(()=>addChat(assistantReply(q),'ai'),120)}
function whatIf(type){const map={ratecut:'خفض الفائدة يميل لدعم الذهب إذا تراجعت العوائد والدولار. التأثير الفعلي يعتمد على سبب الخفض وما كان السوق قد سعّره مسبقاً.',usd:'قوة الدولار عادةً تضغط على الذهب المقوّم بالدولار، خصوصاً إذا رافقها ارتفاع في العوائد الحقيقية.',war:'التصعيد الجيوسياسي قد يزيد طلب الملاذ الآمن ويرفع التقلب؛ لا يعني ذلك صعوداً خطياً أو فورياً.',peace:'التهدئة قد تخفف علاوة الملاذ الآمن، لكن الفائدة والدولار والتضخم قد يبقون العوامل المسيطرة.'};$('whatIfResult').textContent=map[type]||'اختر سيناريو.'}document.querySelectorAll('[data-whatif]').forEach(b=>b.onclick=()=>whatIf(b.dataset.whatif));
$('assistantSend').onclick=()=>askAssistant();$('assistantInput').addEventListener('keydown',e=>{if(e.key==='Enter')askAssistant()});document.querySelectorAll('.quick-prompts button').forEach(b=>b.onclick=()=>askAssistant(b.textContent));$('assistantMic').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){alert('المتصفح لا يدعم الإدخال الصوتي هنا. استخدم الكتابة.');return}const r=new SR();r.lang='ar-LB';r.interimResults=false;r.onresult=e=>{const q=e.results[0][0].transcript;$('assistantInput').value=q;askAssistant(q)};r.onerror=()=>alert('تعذر التقاط الصوت.');r.start()};
