$('importJournalFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('حجم الملف كبير');const entries=J.importBackup(JSON.parse(await file.text()));forecastJournal=J.merge(forecastJournal,entries);saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal);renderAccuracy();alert('تم استيراد الأرشيف؛ نتائجه غير محسوبة كدقة موثقة')}catch{alert('ملف السجل غير صالح؛ لم يتغيّر السجل')}e.target.value=''};
(async()=>{if(!await verify())return;Object.entries(C.theme||{}).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));$('loading').classList.add('hide');macro={...macro,status:'loading',quality:0,compositeScore:null,factors:{},reasonsAr:[],reasons:[]};remoteForecast=null;calendar=readJSON('gold_calendar_cache',calendar);openPage('home');renderHome();loadPrefsUi();renderPaper();renderAccuracy();physicalPreset();if(legacyHolding&&!physicalPieces.length){$('grams').value=legacyHolding.grams;$('cost').value=legacyHolding.cost}renderPhysical();renderRecorder();drawChart();if(price>0)render();fetchLive();fetchCandles();syncJournal();fetchIntelligence(true);fetchCalendar(true);setInterval(syncJournal,300000);countdownTimer=setInterval(updateTime,1000);setInterval(()=>fetchIntelligence(false),60000);setInterval(()=>fetchCalendar(false),60000);initPush();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(console.warn)})();
